// Generates public/d2/d2svgassets.js from D2's d2renderers/d2svg embedded files (v0.9.0): node genassets.mjs <d2 source dir>
import fs from 'node:fs';
import path from 'node:path';
const src = path.join(process.argv[2], 'd2renderers/d2svg');
const rd = (f) => fs.readFileSync(path.join(src, f), 'utf8');
const out = `// This Source Code Form is subject to the terms of the Mozilla Public License, v. 2.0.
// If a copy of the MPL was not distributed with this file, You can obtain one at https://mozilla.org/MPL/2.0/.
//
// Generated by tools/d2ref/genassets.mjs from D2 v0.9.0 d2renderers/d2svg (go:embed files). Do not edit.

export const TooltipIcon = ${JSON.stringify(rd('tooltip.svg'))};
export const LinkIcon = ${JSON.stringify(rd('link.svg'))};
export const BaseStylesheet = ${JSON.stringify(rd('style.css'))};
export const dots = ${JSON.stringify(rd('dots.txt'))};
export const lines = ${JSON.stringify(rd('lines.txt'))};
`;
fs.writeFileSync(new URL('../../public/d2/d2svgassets.js', import.meta.url), out);
